referenceSolutions.javascript:
export function solve(value, edit) {
  const copy = (x) =>
    Array.isArray(x)
      ? x.map(copy)
      : x !== null && typeof x === "object"
        ? Object.fromEntries(Object.entries(x).map(([k, v]) => [k, copy(v)]))
        : x;
  const clone = copy(value);
  let parent = clone;
  for (const k of edit.path.slice(0, -1)) parent = parent[k];
  parent[edit.path[edit.path.length - 1]] = copy(edit.value);
  return { original: value, clone };
}

